func:
var mix_ready = msg.payload[65];

if (mix_ready == true && global.get('estado_anterior') == false){
    // SE DETECTO FLANCO ASCENDENTE (HACER REGISTRO DE BATCH)
    global.set('estado_mezcla','MEZCLA LISTA');
    msg.payload = global.get('estado_mezcla');

    // HACER REGISTRO DE BATCH EN BASE DE DATOS
    msg.payload = 'SAVE_DATA';

    // MANDAR VARIABLE A TRUE PARA HACER CAMBIO DE ESTADO Y DIFERENCIAR FLANCO
    global.set('estado_anterior', true);
};

if (mix_ready == true && global.get('estado_anterior') == true) {
    // ESTADO DE MEZCLA SIGUE LISTA (INDICAR EN DASH)
    global.set('estado_mezcla', 'ESPERANDO RESET DE CICLO');
    msg.payload = global.get('estado_mezcla');
};

if (mix_ready == false && global.get('estado_anterior') == false) {
    // SE DETECTO FLANCO DESCENDENTE (HACER RESET DE SER NECESARIO)
    global.set('estado_mezcla', 'PREPARANDO MEZCLA');
    msg.payload = global.get('estado_mezcla');

    // MANDAR VARIABLE A FALSE PARA REINICIAR CICLO Y DETECTAR FLANCO ASCENDENTE POSTERIORMENTE
    global.set('estado_anterior', false);
}

if (mix_ready == false && global.get('estado_anterior') == true) {
    // SE DETECTO FLANCO DESCENDENTE (HACER RESET DE SER NECESARIO)
    global.set('estado_mezcla', 'CICLO REINICIADO');
    msg.payload = global.get('estado_mezcla');

    // MANDAR VARIABLE A FALSE PARA REINICIAR CICLO Y DETECTAR FLANCO ASCENDENTE POSTERIORMENTE
    global.set('estado_anterior', false);
}


return msg;

